// ── Scene Image Generation & Calm Preview for Proseview ────────────────────
// One-click scene illustrations generated by Codex, Agy, or MCP-backed Claude:
// - 1-click toolbar icon generates immediately when no preview/image exists
// - Compact calm popover with built-in style thumbnails, agent picker & note
// - Non-blocking inline progress & preview card above the scene prose
// - Inline "Refine this image" (image-to-image) + "Fresh take" + "Iterate in chat"
// - 1-click "Insert into scene" saves to <scene_dir>/assets/<scene>.<ext>
(function() {
    var _siScene = null;
    var _siStatus = null;
    var _siSettingsData = null;
    var _siSelectedAgent = 'codex';
    var _siSelectedStyle = 'ink_watercolor';
    var _siNote = '';
    var _siSteerOpen = false;
    var _siPromptOpen = false;
    var _siPollTimer = null;
    var _siClockTimer = null;
    var _siPollInFlight = false;
    var _siStartedAt = 0;

    function _siEsc(s) {
        if (s === null || s === undefined) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function _siFormatClock(sec) {
        var s = Math.max(0, Math.floor(sec || 0));
        var m = Math.floor(s / 60);
        var rem = s % 60;
        return m + ':' + (rem < 10 ? '0' : '') + rem;
    }

    function _siPost(url, body) {
        return fetch(url, {
            method: 'POST',
            headers: pvHeaders(),
            body: JSON.stringify(body || {})
        }).then(function(r) {
            return r.json().then(function(data) {
                if (!r.ok || data.ok === false) {
                    throw new Error((data && data.error) || 'Scene image request failed');
                }
                return data;
            });
        });
    }

    function _siToast(msg, isError) {
        if (typeof sidebarShowToast === 'function') {
            sidebarShowToast(msg, !!isError);
        } else if (typeof showToast === 'function') {
            showToast(msg);
        }
    }

    function _siCurrentScene() {
        if (typeof paths !== 'undefined' && typeof curIdx !== 'undefined' && curIdx >= 0 && paths[curIdx]) {
            return paths[curIdx];
        }
        return _siScene || '';
    }

    function _siStyles() {
        return (_siSettingsData && _siSettingsData.styles) || [
            {id: 'ink_watercolor', name: 'Ink & Watercolor', tagline: 'Warm chiaroscuro & paper grain', thumb: '/assets/scene-styles/ink_watercolor.jpg'},
            {id: 'woodcut', name: 'Woodcut & Engraving', tagline: 'Monochrome linocut on cream paper', thumb: '/assets/scene-styles/woodcut.jpg'},
            {id: 'film_still', name: '35mm Film Still', tagline: 'Cinematic natural grain & light', thumb: '/assets/scene-styles/film_still.jpg'},
            {id: 'charcoal', name: 'Charcoal & Pencil', tagline: 'Expressive sketchbook shading', thumb: '/assets/scene-styles/charcoal.jpg'},
            {id: 'oil_painting', name: 'Oil Painting', tagline: 'Classical brushwork & deep mood', thumb: '/assets/scene-styles/oil_painting.jpg'},
            {id: 'gouache', name: 'Minimalist Gouache', tagline: 'Matte mid-century book-jacket art', thumb: '/assets/scene-styles/gouache.jpg'}
        ];
    }

    function _siStyleName(id) {
        var found = _siStyles().find(function(s) { return s.id === id; });
        return found ? found.name : 'Custom style';
    }

    function _siAgentLabel(agent) {
        if (agent === 'agy') return 'Agy';
        if (agent === 'claude') return 'Claude';
        return 'Codex';
    }

    function _siClaudeMcpAvailable() {
        var caps = _siSettingsData && _siSettingsData.capabilities && _siSettingsData.capabilities.claude;
        return !!(caps && caps.mcp_detected);
    }

    function _siAgentAvailable(agent) {
        if (window.PROSEVIEW_STATIC) return false;
        if (agent === 'claude' && !_siClaudeMcpAvailable()) return false;
        var rows = (typeof _discussAgentAvailability === 'object' && _discussAgentAvailability) || {};
        return !rows[agent] || rows[agent].available !== false;
    }

    function _siEnsureMetaLoaded() {
        if (window.PROSEVIEW_STATIC) return Promise.resolve(null);
        if (_siSettingsData) return Promise.resolve(_siSettingsData);
        return fetch('/api/discuss/scene-image-settings', {headers: pvHeaders()})
            .then(function(r) { return r.json(); })
            .then(function(data) {
                if (data && data.ok && data.settings) {
                    _siSettingsData = data.settings;
                    var book = data.settings.book || {};
                    if (book.agent) _siSelectedAgent = book.agent;
                    if (book.style_preset) _siSelectedStyle = book.style_preset;
                    if (_siSelectedAgent === 'claude' && !_siClaudeMcpAvailable()) {
                        _siSelectedAgent = 'codex';
                    }
                    syncSceneImageToolbarState();
                    renderSceneImagePopover();
                }
                return _siSettingsData;
            })
            .catch(function() { return null; });
    }

    function _siStopPolling() {
        if (_siPollTimer) { clearInterval(_siPollTimer); _siPollTimer = null; }
        if (_siClockTimer) { clearInterval(_siClockTimer); _siClockTimer = null; }
        _siPollInFlight = false;
    }

    function _siStartPolling(scenePath) {
        _siStopPolling();
        _siStartedAt = Date.now() - ((_siStatus && _siStatus.elapsed_seconds ? _siStatus.elapsed_seconds : 0) * 1000);
        _siClockTimer = setInterval(function() {
            var clock = document.getElementById('sceneImageGenClock');
            if (clock) {
                clock.textContent = _siFormatClock((Date.now() - _siStartedAt) / 1000);
            }
        }, 500);
        _siPollTimer = setInterval(function() {
            if (_siPollInFlight || _siCurrentScene() !== scenePath) return;
            _siPollInFlight = true;
            fetch('/api/scene/image/status?path=' + encodeURIComponent(scenePath), {headers: pvHeaders()})
                .then(function(r) { return r.json(); })
                .then(function(data) {
                    if (_siCurrentScene() !== scenePath) return;
                    _siStatus = data;
                    if (!data.active) {
                        _siStopPolling();
                        if (data.error) _siToast(data.error, true);
                    }
                    syncSceneImageToolbarState();
                    renderSceneImageStage();
                    renderSceneImagePopover();
                })
                .catch(function() {})
                .finally(function() { _siPollInFlight = false; });
        }, 1200);
    }

    function loadSceneImageState(scenePath) {
        _siScene = scenePath;
        _siSteerOpen = false;
        _siPromptOpen = false;
        _siStopPolling();
        if (window.PROSEVIEW_STATIC || !scenePath) {
            _siStatus = null;
            syncSceneImageToolbarState();
            renderSceneImageStage();
            return;
        }
        _siEnsureMetaLoaded();
        fetch('/api/scene/image/status?path=' + encodeURIComponent(scenePath), {headers: pvHeaders()})
            .then(function(r) { return r.json(); })
            .then(function(data) {
                if (_siCurrentScene() !== scenePath) return;
                _siStatus = data;
                if (data && data.active) {
                    _siStartPolling(scenePath);
                }
                syncSceneImageToolbarState();
                renderSceneImageStage();
                renderSceneImagePopover();
            })
            .catch(function() {});
    }

    function syncSceneImageToolbarState() {
        var btn = document.getElementById('sceneImageBtn');
        var dot = document.getElementById('sceneImageDot');
        var wrap = document.getElementById('sceneImageMenuWrap');
        if (!btn) return;
        if (window.PROSEVIEW_STATIC) {
            if (wrap) wrap.hidden = true;
            return;
        }
        if (wrap) wrap.hidden = false;
        var active = !!(_siStatus && _siStatus.active);
        var hasPreview = !!(_siStatus && _siStatus.has_preview);
        var hasEmbedded = !!(_siStatus && _siStatus.embedded);
        btn.classList.toggle('is-active', active || hasPreview);
        btn.classList.toggle('is-generating', active);
        if (dot) dot.hidden = !hasPreview;
        if (active) {
            btn.title = 'Creating scene illustration… (click for options)';
        } else if (hasPreview) {
            btn.title = 'Scene image preview ready — click for styles and options';
        } else if (hasEmbedded) {
            btn.title = 'Scene image options (styles, refine, regenerate)';
        } else {
            btn.title = 'Generate ' + _siStyleName(_siSelectedStyle) + ' scene image (1 click)';
        }
    }

    function handleSceneImageToolbarClick() {
        if (window.PROSEVIEW_STATIC) return;
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        var active = !!(_siStatus && _siStatus.active);
        var hasPreview = !!(_siStatus && _siStatus.has_preview);
        var hasEmbedded = !!(_siStatus && _siStatus.embedded);
        // True 1-click calm generation when scene has no preview/image yet.
        if (!active && !hasPreview && !hasEmbedded) {
            if (typeof closeSceneToolbarMenus === 'function') closeSceneToolbarMenus();
            _siEnsureMetaLoaded().then(function() {
                startSceneImageGeneration({refine: false});
            });
            return;
        }
        openSceneImagePopover();
    }

    function toggleSceneImagePopover(trigger) {
        if (window.PROSEVIEW_STATIC) return;
        _siEnsureMetaLoaded().then(function() {
            renderSceneImagePopover();
            if (typeof toggleSceneToolbarMenu === 'function') {
                toggleSceneToolbarMenu('sceneImageMenu', trigger || document.getElementById('sceneImageOptionsBtn'));
            }
        });
    }

    function openSceneImagePopover() {
        if (window.PROSEVIEW_STATIC) return;
        _siEnsureMetaLoaded().then(function() {
            renderSceneImagePopover();
            var menu = document.getElementById('sceneImageMenu');
            if (menu && menu.hidden && typeof toggleSceneToolbarMenu === 'function') {
                toggleSceneToolbarMenu('sceneImageMenu', document.getElementById('sceneImageOptionsBtn'));
            }
        });
    }

    function selectSceneImageStyle(styleId) {
        _siSelectedStyle = styleId;
        syncSceneImageToolbarState();
        renderSceneImagePopover();
    }

    function selectSceneImageAgent(agent) {
        if (!_siAgentAvailable(agent)) return;
        _siSelectedAgent = agent;
        renderSceneImagePopover();
    }

    function startSceneImageGeneration(opts) {
        opts = opts || {};
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        var note = opts.note !== undefined ? String(opts.note) : _siNote;
        var styleId = opts.styleId || _siSelectedStyle || 'ink_watercolor';
        var agent = opts.agent || _siSelectedAgent || 'codex';
        if (agent === 'claude' && !_siClaudeMcpAvailable()) {
            _siToast('Claude CLI has no built-in image generator. Choose Codex or Agy, or connect an image MCP server.', true);
            return;
        }
        _siSelectedStyle = styleId;
        _siSelectedAgent = agent;
        _siNote = note.trim();
        _siSteerOpen = false;
        _siPromptOpen = false;
        if (typeof closeSceneToolbarMenus === 'function') closeSceneToolbarMenus();

        _siStatus = {
            ok: true,
            active: true,
            scene_path: scenePath,
            agent: agent,
            style_id: styleId,
            style_name: _siStyleName(styleId),
            note: _siNote,
            refine: !!opts.refine,
            elapsed_seconds: 0
        };
        syncSceneImageToolbarState();
        renderSceneImageStage();

        _siPost('/api/scene/image/generate', {
            path: scenePath,
            agent: agent,
            style_id: styleId,
            note: _siNote,
            refine: !!opts.refine
        }).then(function(data) {
            if (_siCurrentScene() !== scenePath) return;
            _siStatus = data;
            _siStartPolling(scenePath);
            syncSceneImageToolbarState();
            renderSceneImageStage();
        }).catch(function(err) {
            if (_siCurrentScene() !== scenePath) return;
            _siStatus = {ok: true, active: false, scene_path: scenePath, error: err.message};
            syncSceneImageToolbarState();
            renderSceneImageStage();
            _siToast(err.message, true);
        });
    }

    function cancelSceneImageGeneration() {
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        _siStopPolling();
        _siPost('/api/scene/image/cancel', {path: scenePath})
            .then(function() {
                loadSceneImageState(scenePath);
                _siToast('Scene image generation cancelled.');
            })
            .catch(function() { loadSceneImageState(scenePath); });
    }

    function insertSceneImage(chatImageId, takeId) {
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        _siPost('/api/scene/image/insert', {
            path: scenePath,
            chat_image_id: chatImageId || '',
            take_id: takeId || ''
        }).then(function(res) {
            _siToast('Inserted into scene · Saved to ' + res.asset_repo_path);
            loadSceneImageState(scenePath);
            if (typeof refreshContent === 'function') {
                refreshContent();
            }
            // Bust in-memory browser bitmap cache when replacing an image at the same filename.
            if (res && res.asset_url) {
                var targetUrl = String(res.asset_url);
                setTimeout(function() {
                    document.querySelectorAll('#sceneProseHost img').forEach(function(img) {
                        var rawSrc = img.getAttribute('src') || '';
                        if (rawSrc === targetUrl || rawSrc.split('?')[0] === targetUrl) {
                            img.src = targetUrl + '?v=' + Date.now();
                        }
                    });
                }, 250);
            }
        }).catch(function(err) {
            _siToast(err.message, true);
        });
    }

    function selectSceneImageTake(takeId) {
        var scenePath = _siCurrentScene();
        if (!scenePath || !takeId) return;
        _siPost('/api/scene/image/select', {path: scenePath, take_id: takeId})
            .then(function(res) {
                if (_siCurrentScene() !== scenePath || !res || !res.preview) return;
                if (!_siStatus) _siStatus = {ok: true, active: false, scene_path: scenePath};
                _siStatus.has_preview = true;
                _siStatus.preview = res.preview;
                renderSceneImageStage();
            })
            .catch(function(err) { _siToast(err.message, true); });
    }

    function removeSceneImageFromScene() {
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        _siPost('/api/scene/image/remove', {path: scenePath})
            .then(function(res) {
                if (res.removed) {
                    _siToast('Removed image from scene (backup saved in History).');
                    if (typeof refreshContent === 'function') refreshContent();
                }
                loadSceneImageState(scenePath);
            })
            .catch(function(err) {
                _siToast(err.message, true);
            });
    }

    function dismissSceneImagePreview() {
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        _siPost('/api/scene/image/dismiss', {path: scenePath})
            .then(function() {
                _siNote = '';
                _siSteerOpen = false;
                loadSceneImageState(scenePath);
            })
            .catch(function(err) { _siToast(err.message, true); });
    }

    function promoteChatImageToScenePreview(imageId) {
        var scenePath = _siCurrentScene();
        if (!scenePath || !imageId) return;
        _siPost('/api/scene/image/promote', {path: scenePath, chat_image_id: imageId})
            .then(function() {
                _siToast('Loaded image as scene preview.');
                loadSceneImageState(scenePath);
            })
            .catch(function(err) { _siToast(err.message, true); });
    }

    function iterateSceneImageInChat(explicitSrc) {
        var scenePath = _siCurrentScene();
        if (!scenePath) return;
        var preview = _siStatus && _siStatus.preview;
        var targetAgent = (_siStatus && _siStatus.agent) || (preview && preview.agent) || _siSelectedAgent || 'codex';
        if (targetAgent === 'claude' && !_siClaudeMcpAvailable()) targetAgent = 'codex';

        if (typeof showDiscussAgentTab === 'function') {
            showDiscussAgentTab(targetAgent);
        }
        // When invoked from an existing embedded image on disk (no live preview),
        // pre-fill a helpful reference; when invoked from a live preview/job,
        // the request and image are already in the chat thread — just focus input!
        setTimeout(function() {
            var input = document.getElementById('discussInput');
            if (!input) return;
            if (explicitSrc && !preview) {
                var styleLabel = _siStyleName(_siSelectedStyle);
                var seed = 'Let\'s iterate on the scene illustration `' + explicitSrc + '` (' + styleLabel + ').\nAdjustments I\'d like: ';
                input.value = seed;
                input.setSelectionRange(seed.length, seed.length);
                input.dispatchEvent(new Event('input', {bubbles: true}));
            }
            input.focus();
        }, 120);
    }

    function renderSceneImagePopover() {
        var menu = document.getElementById('sceneImageMenu');
        if (!menu) return;
        var active = !!(_siStatus && _siStatus.active);
        var hasPreview = !!(_siStatus && _siStatus.has_preview);
        var hasEmbedded = !!(_siStatus && _siStatus.embedded);
        var stateLabel = active ? 'Generating…' : (hasPreview ? 'Preview ready' : (hasEmbedded ? 'In scene' : '1-click ready'));
        var styles = _siStyles();
        var caps = (_siSettingsData && _siSettingsData.capabilities) || {};

        var styleCards = styles.map(function(s) {
            var sel = _siSelectedStyle === s.id;
            return '<button type="button" class="scene-image-style-card' + (sel ? ' is-selected' : '') + '"'
                + ' data-style-id="' + _siEsc(s.id) + '" title="' + _siEsc(s.tagline || s.name) + '">'
                + '<img src="' + _siEsc(s.thumb) + '" alt="' + _siEsc(s.name) + '" loading="lazy">'
                + '<span class="scene-image-style-card-name">' + _siEsc(s.name) + '</span>'
                + '</button>';
        }).join('');

        var agents = [
            {id: 'codex', label: 'Codex CLI', note: (caps.codex && caps.codex.note) || 'Native image generation'},
            {id: 'agy', label: 'Agy CLI', note: (caps.agy && caps.agy.note) || 'Native image-generator'},
            {id: 'claude', label: 'Claude CLI', note: (caps.claude && caps.claude.note) || 'Requires an image MCP server in Claude Code'}
        ];
        var agentRows = agents.map(function(a) {
            var avail = _siAgentAvailable(a.id);
            var sel = _siSelectedAgent === a.id && avail;
            return '<button type="button" class="scene-image-agent-row' + (sel ? ' is-selected' : '') + (!avail ? ' is-disabled' : '') + '"'
                + ' data-agent="' + a.id + '"' + (!avail ? ' disabled' : '') + '>'
                + '<span class="scene-image-agent-copy">'
                + '<span class="scene-image-agent-name">' + _siEsc(a.label) + '</span>'
                + '<span class="scene-image-agent-note">' + _siEsc(a.note) + '</span>'
                + '</span>'
                + (sel ? '<span class="scene-image-agent-badge">Active</span>' : '')
                + '</button>';
        }).join('');

        var canRefine = hasPreview || hasEmbedded;
        menu.innerHTML = ''
            + '<div class="scene-image-pop-head">'
            +   '<span class="scene-toolbar-menu-heading" style="padding:0">Scene Image</span>'
            +   '<span class="scene-image-state-pill">' + _siEsc(stateLabel) + '</span>'
            + '</div>'
            + '<div class="scene-image-pop-section">'
            +   '<div class="scene-image-pop-label-row"><span>Style</span><span class="scene-image-pop-muted">' + _siEsc(_siStyleName(_siSelectedStyle)) + '</span></div>'
            +   '<div class="scene-image-style-grid">' + styleCards + '</div>'
            + '</div>'
            + '<div class="scene-image-pop-section">'
            +   '<div class="scene-image-pop-label-row"><span>Agent</span></div>'
            +   '<div class="scene-image-agent-list">' + agentRows + '</div>'
            + '</div>'
            + '<div class="scene-image-pop-section">'
            +   '<div class="scene-image-pop-label-row"><label for="sceneImagePopNote">Direction for this scene</label><span class="scene-image-pop-muted">Optional</span></div>'
            +   '<textarea id="sceneImagePopNote" class="scene-image-pop-textarea" rows="2" placeholder="Leave blank for automatic art, or steer framing, mood, lighting…">' + _siEsc(_siNote) + '</textarea>'
            + '</div>'
            + '<div class="scene-image-pop-foot">'
            +   '<button type="button" class="scene-image-btn-ghost" id="sceneImageOpenSettingsBtn">All styles &amp; prompt…</button>'
            +   '<div class="scene-image-pop-actions">'
            +     (canRefine ? '<button type="button" class="scene-image-btn-quiet" id="sceneImagePopRefineBtn">Refine</button>' : '')
            +     '<button type="button" class="scene-image-btn-primary" id="sceneImagePopGenBtn">' + (hasPreview ? 'Fresh take' : 'Generate') + '</button>'
            +   '</div>'
            + '</div>';

        menu.querySelectorAll('.scene-image-style-card').forEach(function(el) {
            el.onclick = function() { selectSceneImageStyle(el.dataset.styleId); };
        });
        menu.querySelectorAll('.scene-image-agent-row:not([disabled])').forEach(function(el) {
            el.onclick = function() { selectSceneImageAgent(el.dataset.agent); };
        });
        var noteEl = menu.querySelector('#sceneImagePopNote');
        if (noteEl) {
            noteEl.oninput = function() { _siNote = noteEl.value; };
        }
        var settingsBtn = menu.querySelector('#sceneImageOpenSettingsBtn');
        if (settingsBtn) {
            settingsBtn.onclick = function() {
                if (typeof closeSceneToolbarMenus === 'function') closeSceneToolbarMenus();
                if (typeof openSceneImageSettings === 'function') openSceneImageSettings();
            };
        }
        var genBtn = menu.querySelector('#sceneImagePopGenBtn');
        if (genBtn) {
            genBtn.onclick = function() {
                startSceneImageGeneration({note: noteEl ? noteEl.value : _siNote, refine: false});
            };
        }
        var refineBtn = menu.querySelector('#sceneImagePopRefineBtn');
        if (refineBtn) {
            refineBtn.onclick = function() {
                startSceneImageGeneration({note: noteEl ? noteEl.value : _siNote, refine: true});
            };
        }
    }

    function renderSceneImageStage() {
        var host = document.getElementById('sceneImageHost');
        if (!host) return;
        if (window.PROSEVIEW_STATIC || !_siStatus) {
            host.replaceChildren();
            return;
        }

        if (_siStatus.active) {
            var styleLabel = _siStatus.style_name || _siStyleName(_siStatus.style_id);
            var agentLabel = _siAgentLabel(_siStatus.agent);
            var verb = _siStatus.refine ? 'Refining' : 'Creating';
            var noteHtml = _siStatus.note
                ? '<div class="scene-image-gen-note">Note: “' + _siEsc(_siStatus.note) + '”</div>'
                : '';
            host.innerHTML = ''
                + '<div class="scene-image-gen-card" role="status" aria-live="polite">'
                +   '<div class="scene-image-gen-row">'
                +     '<div class="scene-image-gen-left">'
                +       '<span class="scene-image-pulse-dot" aria-hidden="true"></span>'
                +       '<span class="scene-image-gen-title">' + verb + ' <strong>' + _siEsc(styleLabel) + '</strong> scene image with ' + _siEsc(agentLabel) + '…</span>'
                +       '<span id="sceneImageGenClock" class="scene-image-gen-clock">' + _siFormatClock(_siStatus.elapsed_seconds) + '</span>'
                +     '</div>'
                +     '<div class="scene-image-pop-actions">'
                +       '<button type="button" class="scene-image-btn-ghost" id="sceneImageViewChatBtn">View in chat</button>'
                +       '<button type="button" class="scene-image-btn-ghost" id="sceneImageCancelBtn">Cancel</button>'
                +     '</div>'
                +   '</div>'
                +   noteHtml
                +   '<div class="scene-image-shimmer"></div>'
                + '</div>';
            var viewChatBtn = host.querySelector('#sceneImageViewChatBtn');
            if (viewChatBtn) viewChatBtn.onclick = function() { iterateSceneImageInChat(); };
            var cancelBtn = host.querySelector('#sceneImageCancelBtn');
            if (cancelBtn) cancelBtn.onclick = cancelSceneImageGeneration;
            return;
        }

        if (_siStatus.error && !_siStatus.has_preview) {
            host.innerHTML = ''
                + '<div class="scene-image-error-card" role="alert">'
                +   '<div class="scene-image-error-text">' + _siEsc(_siStatus.error) + '</div>'
                +   '<div class="scene-image-error-actions">'
                +     '<button type="button" class="scene-image-btn-quiet" id="sceneImageRetryBtn">Try again</button>'
                +     '<button type="button" class="scene-image-btn-ghost" id="sceneImageDismissErrBtn">Dismiss</button>'
                +   '</div>'
                + '</div>';
            var retryBtn = host.querySelector('#sceneImageRetryBtn');
            if (retryBtn) retryBtn.onclick = function() { openSceneImagePopover(); };
            var dismissErr = host.querySelector('#sceneImageDismissErrBtn');
            if (dismissErr) dismissErr.onclick = function() { _siStatus.error = ''; renderSceneImageStage(); };
            return;
        }

        if (!_siStatus.has_preview || !_siStatus.preview) {
            host.replaceChildren();
            return;
        }

        var prev = _siStatus.preview;
        var stylePills = _siStyles().map(function(s) {
            var sel = prev.style_id === s.id;
            return '<button type="button" class="scene-image-style-pill' + (sel ? ' is-selected' : '') + '" data-style-id="' + _siEsc(s.id) + '">'
                + '<img src="' + _siEsc(s.thumb) + '" alt="">'
                + '<span>' + _siEsc(s.name) + '</span>'
                + '</button>';
        }).join('');

        var steerHtml = _siSteerOpen ? (''
            + '<div class="scene-image-steer-panel">'
            +   '<div class="scene-image-steer-label">Try another built-in style (1 click):</div>'
            +   '<div class="scene-image-style-pills">' + stylePills + '</div>'
            +   '<div class="scene-image-steer-row">'
            +     '<input type="text" id="sceneImageInlineNote" class="scene-image-inline-input" value="' + _siEsc(_siNote || prev.note || '') + '" placeholder="Describe an adjustment (e.g., warmer amber light, focus on the window)…">'
            +     '<button type="button" class="scene-image-btn-primary" id="sceneImageRefineBtn" title="Edit this preview image using your note">Refine image</button>'
            +     '<button type="button" class="scene-image-btn-quiet" id="sceneImageFreshBtn" title="Generate a brand-new composition">Fresh take</button>'
            +   '</div>'
            + '</div>'
        ) : '';

        var promptText = prev.revised_prompt || prev.prompt_used || '';
        var promptHtml = (_siPromptOpen && promptText)
            ? '<pre class="scene-image-prompt-box">' + _siEsc(promptText) + '</pre>'
            : '';

        var takeCount = prev.take_count || 1;
        var takeIndex = prev.take_index || 1;
        var takesList = Array.isArray(prev.takes) ? prev.takes : [];
        var takeNavHtml = '';
        if (takeCount > 1 && takesList.length === takeCount) {
            var prevTake = takeIndex > 1 ? takesList[takeIndex - 2] : null;
            var nextTake = takeIndex < takeCount ? takesList[takeIndex] : null;
            takeNavHtml = ''
                + '<span class="scene-image-take-nav" aria-label="Preview takes">'
                +   '<button type="button" class="scene-image-take-btn" id="sceneImagePrevTake"'
                +     (prevTake ? ' data-take-id="' + _siEsc(prevTake.id) + '" title="Previous take (' + (takeIndex - 1) + ' of ' + takeCount + ')"' : ' disabled title="First take"')
                +     ' aria-label="Previous take">&#8249;</button>'
                +   '<span class="scene-image-take-count">' + takeIndex + ' / ' + takeCount + '</span>'
                +   '<button type="button" class="scene-image-take-btn" id="sceneImageNextTake"'
                +     (nextTake ? ' data-take-id="' + _siEsc(nextTake.id) + '" title="Next take (' + (takeIndex + 1) + ' of ' + takeCount + ')"' : ' disabled title="Latest take"')
                +     ' aria-label="Next take">&#8250;</button>'
                + '</span>';
        }

        host.innerHTML = ''
            + '<figure class="scene-image-preview-card">'
            +   '<div class="scene-image-preview-frame">'
            +     '<img src="' + _siEsc(prev.preview_url) + '" alt="' + _siEsc(prev.alt || 'Scene illustration preview') + '">'
            +   '</div>'
            +   '<figcaption class="scene-image-preview-bar">'
            +     '<div class="scene-image-preview-meta">'
            +       '<span class="scene-image-preview-dot" aria-hidden="true"></span>'
            +       '<span>Preview · ' + _siEsc(prev.style_name || _siStyleName(prev.style_id)) + ' · ' + _siEsc(_siAgentLabel(prev.agent)) + '</span>'
            +       takeNavHtml
            +       (promptText ? '<button type="button" class="scene-image-link-btn" id="sceneImageTogglePromptBtn">' + (_siPromptOpen ? 'Hide prompt' : 'Prompt') + '</button>' : '')
            +     '</div>'
            +     '<div class="scene-image-preview-actions">'
            +       '<button type="button" class="scene-image-btn-ghost" id="sceneImageDismissBtn">Dismiss</button>'
            +       '<button type="button" class="scene-image-btn-ghost" id="sceneImageChatBtn">Iterate in chat</button>'
            +       '<button type="button" class="scene-image-btn-quiet" id="sceneImageSteerBtn">' + (_siSteerOpen ? 'Close' : 'Style / refine…') + '</button>'
            +       '<button type="button" class="scene-image-btn-primary" id="sceneImageInsertBtn">Insert into scene</button>'
            +     '</div>'
            +   '</figcaption>'
            +   promptHtml
            +   steerHtml
            + '</figure>';

        var prevTakeBtn = host.querySelector('#sceneImagePrevTake');
        if (prevTakeBtn && prevTakeBtn.dataset.takeId) {
            prevTakeBtn.onclick = function() { selectSceneImageTake(prevTakeBtn.dataset.takeId); };
        }
        var nextTakeBtn = host.querySelector('#sceneImageNextTake');
        if (nextTakeBtn && nextTakeBtn.dataset.takeId) {
            nextTakeBtn.onclick = function() { selectSceneImageTake(nextTakeBtn.dataset.takeId); };
        }
        var togglePrompt = host.querySelector('#sceneImageTogglePromptBtn');
        if (togglePrompt) togglePrompt.onclick = function() { _siPromptOpen = !_siPromptOpen; renderSceneImageStage(); };
        var dismissBtn = host.querySelector('#sceneImageDismissBtn');
        if (dismissBtn) dismissBtn.onclick = dismissSceneImagePreview;
        var chatBtn = host.querySelector('#sceneImageChatBtn');
        if (chatBtn) chatBtn.onclick = function() { iterateSceneImageInChat(); };
        var steerBtn = host.querySelector('#sceneImageSteerBtn');
        if (steerBtn) steerBtn.onclick = function() {
            _siSteerOpen = !_siSteerOpen;
            renderSceneImageStage();
            if (_siSteerOpen) {
                var inp = document.getElementById('sceneImageInlineNote');
                if (inp) inp.focus();
            }
        };
        var insertBtn = host.querySelector('#sceneImageInsertBtn');
        if (insertBtn) insertBtn.onclick = function() { insertSceneImage('', prev.take_id || ''); };

        host.querySelectorAll('.scene-image-style-pill').forEach(function(pill) {
            pill.onclick = function() {
                var inp = document.getElementById('sceneImageInlineNote');
                startSceneImageGeneration({
                    styleId: pill.dataset.styleId,
                    note: inp ? inp.value : _siNote,
                    refine: false
                });
            };
        });
        var refineBtn = host.querySelector('#sceneImageRefineBtn');
        if (refineBtn) refineBtn.onclick = function() {
            var inp = document.getElementById('sceneImageInlineNote');
            startSceneImageGeneration({note: inp ? inp.value : _siNote, styleId: prev.style_id, refine: true});
        };
        var freshBtn = host.querySelector('#sceneImageFreshBtn');
        if (freshBtn) freshBtn.onclick = function() {
            var inp = document.getElementById('sceneImageInlineNote');
            startSceneImageGeneration({note: inp ? inp.value : _siNote, styleId: prev.style_id, refine: false});
        };
        var inlineInput = host.querySelector('#sceneImageInlineNote');
        if (inlineInput) {
            inlineInput.onkeydown = function(ev) {
                if (ev.key === 'Enter') {
                    ev.preventDefault();
                    startSceneImageGeneration({note: inlineInput.value, styleId: prev.style_id, refine: true});
                }
            };
        }
    }

    // ── Discuss chat card renderer (`proseview:scene-image`) ────────────────
    var _siSeenChatImages = {};

    function renderDiscussSceneImageCard(rawJson, parent) {
        var data = null;
        try { data = JSON.parse(String(rawJson || '').trim()); } catch (e) {}
        if (!data || !data.url || !data.image_id) return;

        // If a brand-new chat image arrives for the active scene, refresh the
        // calm scene preview above the prose so the take switcher stays in sync.
        var curScene = _siCurrentScene();
        if (curScene && (!data.scene_path || data.scene_path === curScene) && !_siSeenChatImages[data.image_id]) {
            _siSeenChatImages[data.image_id] = true;
            if (!(_siStatus && _siStatus.active)) {
                setTimeout(function() {
                    if (_siCurrentScene() === curScene) loadSceneImageState(curScene);
                }, 150);
            }
        }

        var card = document.createElement('div');
        card.className = 'discuss-scene-image-card';

        var img = document.createElement('img');
        img.className = 'discuss-scene-image-thumb';
        img.src = data.url;
        img.alt = data.alt || 'Generated scene illustration';
        img.loading = 'lazy';

        var bar = document.createElement('div');
        bar.className = 'discuss-scene-image-bar';

        var label = document.createElement('span');
        label.className = 'discuss-scene-image-meta';
        label.textContent = 'Generated by ' + _siAgentLabel(data.agent);

        var actions = document.createElement('div');
        actions.className = 'discuss-scene-image-actions';

        var prevBtn = document.createElement('button');
        prevBtn.type = 'button';
        prevBtn.className = 'scene-image-btn-quiet';
        prevBtn.textContent = 'Use as preview';
        prevBtn.onclick = function() { promoteChatImageToScenePreview(data.image_id); };

        var insBtn = document.createElement('button');
        insBtn.type = 'button';
        insBtn.className = 'scene-image-btn-primary';
        insBtn.textContent = 'Insert into scene';
        insBtn.onclick = function() { insertSceneImage(data.image_id); };

        actions.append(prevBtn, insBtn);
        bar.append(label, actions);
        card.append(img, bar);
        parent.appendChild(card);
    }

    // Sync local defaults when Settings › Scene Image saves
    window.syncSceneImageDefaultsFromSettings = function(settings) {
        _siSettingsData = settings;
        if (settings && settings.book) {
            if (settings.book.agent) _siSelectedAgent = settings.book.agent;
            if (settings.book.style_preset) _siSelectedStyle = settings.book.style_preset;
        }
        syncSceneImageToolbarState();
        renderSceneImagePopover();
    };

    window.loadSceneImageState = loadSceneImageState;
    window.renderSceneImageStage = renderSceneImageStage;
    window.handleSceneImageToolbarClick = handleSceneImageToolbarClick;
    window.toggleSceneImagePopover = toggleSceneImagePopover;
    window.openSceneImagePopover = openSceneImagePopover;
    window.removeSceneImageFromScene = removeSceneImageFromScene;
    window.iterateSceneImageInChat = iterateSceneImageInChat;
    window.renderDiscussSceneImageCard = renderDiscussSceneImageCard;

    // If the page opened directly on a #/scene/... hash before this file ran,
    // hydrate the scene's image state right away.
    if (document.documentElement.dataset.view === 'scene') {
        var initialPath = _siCurrentScene();
        if (initialPath) loadSceneImageState(initialPath);
    } else {
        syncSceneImageToolbarState();
    }
})();
